To create a beautiful red heart as a fractal in p5.js and WebGL, we'll use the Mandelbrot set as our foundation. The Mandelbrot set is a well-known fractal that can be used to generate various shapes. We'll modify the algorithm to create a heart-shaped region.

Here's the p5.js code to get us started:
```javascript
let numPoints = 10000;
let points = [];
let heartScale = 0.5;
let heartShift = 0.5;

function setup() {
  createCanvas(600, 600, WEBGL);
  angleMode(DEGREES);
  noStroke();
  colorMode(HSB, 360, 100, 100);
  fill(255, 0, 100, 100); // red heart
  background(0);
}

function draw() {
  rotateX(frameCount * 0.01);
  rotateZ(frameCount * 0.01);
  translate(-width / 2, -height / 2);
  for (let i = 0; i < numPoints; i++) {
    let x = random(-heartScale * width, heartScale * width);
    let y = random(-heartShift * height, heartShift * height);
    let c = complex(x, y);
    let z = complex(0, 0);
    for (let j = 0; j < 100; j++) {
      z = add(z, multiply(c, z));
      if (mag(z) > 2) {
        points.push({ x, y });
        break;
      }
    }
  }
  beginShape(QUADS);
  for (let i = 0; i < points.length; i++) {
    let point = points[i];
    vertex(point.x, point.y, 0);
    if (i > 0) {
      let prevPoint = points[i - 1];
      vertex(prevPoint.x, prevPoint.y, 0);
    }
  }
  endShape();
}

// helper functions
function complex(x, y) {
  return { re: x, im: y };
}

function add(a, b) {
  return { re: a.re + b.re, im: a.im + b.im };
}

function multiply(a, b) {
  return { re: a.re * b.re - a.im * b.im, im: a.re * b.im + a.im * b.re };
}

function mag(z) {
  return sqrt(z.re * z.re + z.im * z.im);
}
```
