const fs = require('fs');

class CodeGenerator {
  constructor(modelPath, tokenizerPath) {
    this.tokenizer = new GPT2Tokenizer();
    this.tokenizer.addSpecialTokens({
      'eos': '<|endoftext|>',
    });
    this.model = new GPT2LMHeadModel();
    this.model.load('pkl', modelPath);
