    const output = this.model.generate(
      inputIds,
      maxLength,
      numReturnSequences,
      2, // no repeat ngram size
      0.7, // temperature
      50, // top k
      0.95 // top p
    );
    return output.map((seq) => this.tokenizer.decode(seq, true));
  }
}

