```React
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ items, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const handleInputValueChange = () => {
      const userInput = inputValue.toLowerCase();
      const filteredSuggestions = items.filter(item => {
        const itemText = item.toLowerCase();
        return itemText.includes(userInput);
      });
      setSuggestions(filteredSuggestions);
    };

    const handleInputChange = event => {
      setInputValue(event.target.value);
      handleInputValueChange();
    };

    const handleKeydown = event => {
      if (event.key === 'ArrowDown') {
        setActiveSuggestionIndex(prevIndex => prevIndex + 1);
      } else if (event.key === 'ArrowUp') {
        setActiveSuggestionIndex(prevIndex => prevIndex - 1);
      } else if (event.key === 'Enter') {
        event.preventDefault();
        onSelect(suggestions[activeSuggestionIndex]);
      }
    };

    document.addEventListener('keydown', handleKeydown);

    return () => {
      document.removeEventListener('keydown', handleKeydown);
    };
  }, [activeSuggestionIndex, inputValue, onSelect, items]);

  const handleMouseClick = item => {
    onSelect(item);
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Type to search..."
      />
      {suggestions.map((item, index) => (
        <div
          key={index}
          className={
            index === activeSuggestionIndex ? 'suggestion active' : 'suggestion'
          }
          onMouseDown={() => handleMouseClick(item)}
        >
          {item}
        </div>
      ))}
    </div>
  );
};

export default Autocomplete;
```

