```csharp
using System;
using System.Net;
using System.Text;
using System.IO;

class HttpServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");
        listener.Start();

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.PathAndQuery == "/hello")
            {
                string response = "<html><body>Hello</body></html>";
                SendResponse(context, System.Text.Encoding.UTF8.GetBytes(response));
            }
            else
            {
                SendErrorResponse(context, "Page not found");
            }
        }
    }

    static void SendResponse(HttpListenerContext context, byte[] response)
    {
        HttpListenerResponse responseStream = context.Response;
        responseStream.ContentType = "text/html";
        responseStream.ContentLength64 = response.Length;
        Stream output = responseStream.GetResponseStream();
        output.Write(response, 0, response.Length);
        output.Close();
    }

    static void SendErrorResponse(HttpListenerContext context, string errorMessage)
    {
        SendResponse(context, Encoding.UTF8.GetBytes($"<html><body>{errorMessage}</body></html>"));
    }
}
```
