        int n = 1000; // размер шага интегрирования
        int numThreads = 4; // количество потоков
        HANDLE threadHandles[numThreads];
        HANDLE mutex; // мьютекс для синхронизации вывода
        HANDLE sem; // семафор для ожидания завершения потоков

        // создаем мьютекс и семафор
        mutex = CreateMutex(nullptr, FALSE, NULL);
        sem = CreateSemaphore(nullptr, 0, 1, NULL);

        // создаем потоки
