```c
// Estructura para representar un nodo del árbol binario
struct Node {
    int value;
    Node* left;
    Node* right;
};

// Función para crear un nuevo nodo
Node* createNode(int value) {
    Node* newNode = new Node();
    newNode->value = value;
    newNode->left = nullptr;
    newNode->right = nullptr;
    return newNode;
}

// Algoritmo de búsqueda en el árbol binario
Node* searchNode(Node* root, int targetValue) {
    if (root == nullptr) {
        return nullptr; // El árbol binario está vacío
    }

    if (root->value == targetValue) {
        return root; // Encontramos el nodo con el valor objetivo
    }

    if (targetValue < root->value) {
        return searchNode(root->left, targetValue); // Buscamos en el subárbol izquierdo
    } else {
        return searchNode(root->right, targetValue); // Buscamos en el subárbol derecho
    }
}

// Función principal para probar el algoritmo de búsqueda
int main() {
    Node* root = createNode(5);
    root->left = createNode(3);
    root->right = createNode(7);
    root->left->left = createNode(2);
    root->left->right = createNode(4);
    root->right->left = createNode(6);
    root->right->right = createNode(8);

    int targetValue = 4;
    Node* result = searchNode(root, targetValue);

    if (result != nullptr) {
        std::cout << "Encontrado el nodo con valor " << targetValue << std::endl;
    } else {
        std::cout << "Nodo no encontrado" << std::endl;
    }

    return 0;
