    procedure RotatePDF(const PDFFilePath: String; const Angle: Real);
  end;

implementation

procedure TPDFRotator.RotatePDF(const PDFFilePath: String; const Angle: Real);
var
  PDF: TAdvPdf;
begin
  PDF := TAdvPdf.Create(nil);
  try
    PDF.LoadFromFile(PDFFilePath);
    PDFPitch := Angle; { Set the rotation angle }
    PDF.SetWidthAndHeight(0, 0); { Reset the width/height }
    PDF.SaveToFile(ExtractFilePath(PDFFilePath) + 'Rotated_' + ExtractFileName(PDFFilePath));
  finally
    FreeAndNil(PDF);
  end;
end;

end.
```
In this example, we create an instance of `TAdvPdf`, load the PDF file using `LoadFromFile`, set the rotation angle using `Pitch`, reset the width and height using `SetWidthAndHeight`, and then save the rotated PDF to a new file using `SaveToFile`.

